PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE doctors (
  id                TEXT PRIMARY KEY,
  mobile            TEXT NOT NULL UNIQUE,       -- verified at signup, used for OTP
  mobile_verified   INTEGER NOT NULL DEFAULT 0,
  email             TEXT,
  full_name         TEXT NOT NULL,
  qualification     TEXT,
  registration_no   TEXT,
  clinic_name       TEXT NOT NULL,
  tagline           TEXT,
  address           TEXT,
  website           TEXT,
  logo_key          TEXT,                        -- R2 object key, not the image
  theme_ink         TEXT DEFAULT '#1B4A34',
  theme_accent      TEXT DEFAULT '#C9973E',
  patient_prefix    TEXT DEFAULT 'TCOS',
  practice_packs    TEXT NOT NULL DEFAULT '[]',  -- JSON array of pack ids
  line              TEXT NOT NULL DEFAULT 'doctor',
  plan              TEXT NOT NULL DEFAULT 'basic',
  feature_overrides TEXT NOT NULL DEFAULT '{}',  -- JSON, admin per-doctor switches
  trial_offer       TEXT,
  trial_ends_on     TEXT,
  status            TEXT NOT NULL DEFAULT 'active', -- active | suspended
  password_hash     TEXT,                        -- PBKDF2, salted, per row
  password_salt     TEXT,
  must_change_password INTEGER NOT NULL DEFAULT 0,
  created_at        TEXT NOT NULL DEFAULT (datetime('now')),
  last_sign_in_at   TEXT
, public_slug TEXT, public_page_on INTEGER NOT NULL DEFAULT 0, public_intro TEXT, public_hours TEXT, custom_domain TEXT, weekly_hours TEXT NOT NULL DEFAULT '{}', certificate_name TEXT, certificate_status TEXT NOT NULL DEFAULT 'not_uploaded', certificate_submitted_at TEXT, product TEXT NOT NULL DEFAULT 'ayurcos', verification_status TEXT NOT NULL DEFAULT 'unverified', verified_at TEXT, verified_by TEXT, verification_note TEXT, custom_domain_status TEXT NOT NULL DEFAULT 'none', custom_domain_checked_at TEXT, custom_domain_active_at TEXT, custom_domain_error TEXT, facility_type TEXT NOT NULL DEFAULT 'clinic', certificate_file_id TEXT REFERENCES files(id), logo_file_id TEXT REFERENCES files(id), hpr_id TEXT, hpr_verified_at TEXT, hfr_id TEXT, hfr_verified_at TEXT, verify_by TEXT, verify_reminded_at TEXT, suspended_reason TEXT, suspended_at TEXT, suspended_by TEXT, council TEXT);
CREATE TABLE sessions (
  token_hash  TEXT PRIMARY KEY,
  doctor_id   TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  expires_at  TEXT NOT NULL,
  user_agent  TEXT,
  revoked_at  TEXT
, user_id TEXT, csrf_hash TEXT);
CREATE TABLE otp_codes (
  id          TEXT PRIMARY KEY,
  purpose     TEXT NOT NULL,          -- doctor_signup | doctor_reset | patient_consent
  mobile      TEXT NOT NULL,
  code_hash   TEXT NOT NULL,
  context     TEXT,                   -- JSON: eg which doctor is requesting consent
  attempts    INTEGER NOT NULL DEFAULT 0,
  consumed_at TEXT,
  expires_at  TEXT NOT NULL,
  created_at  TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE doctor_patients (
  doctor_id     TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  patient_id    TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,
  local_ref     TEXT,                  -- the doctor's own patient number
  first_seen_on TEXT NOT NULL DEFAULT (date('now')),
  last_seen_on  TEXT,
  private_notes TEXT,                  -- never shared, even under consent
  archived_at   TEXT,
  PRIMARY KEY (doctor_id, patient_id)
);
CREATE TABLE visits (
  id           TEXT PRIMARY KEY,
  doctor_id    TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  patient_id   TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,
  visited_on   TEXT NOT NULL,
  visit_type   TEXT,                   -- first | follow_up | online
  complaints   TEXT,
  diagnosis    TEXT,
  vitals       TEXT,                   -- JSON
  findings     TEXT,                   -- JSON, practice-pack fields
  advice       TEXT,
  follow_up_on TEXT,
  created_at   TEXT NOT NULL DEFAULT (datetime('now'))
, status TEXT NOT NULL DEFAULT 'completed', closed_at TEXT, practitioner_id TEXT REFERENCES clinic_users(id), idempotency_key TEXT);
CREATE TABLE prescriptions (
  id          TEXT PRIMARY KEY,
  doctor_id   TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  patient_id  TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,
  visit_id    TEXT REFERENCES visits(id) ON DELETE SET NULL,
  rx_number   TEXT,
  issued_on   TEXT NOT NULL,
  status      TEXT NOT NULL DEFAULT 'draft',  -- draft | issued
  created_at  TEXT NOT NULL DEFAULT (datetime('now'))
, issued_at TEXT, sequence_no INTEGER, amends TEXT, superseded_by TEXT, amend_reason TEXT, practitioner_id TEXT REFERENCES clinic_users(id), idempotency_key TEXT);
CREATE TABLE prescription_items (
  id              TEXT PRIMARY KEY,
  prescription_id TEXT NOT NULL REFERENCES prescriptions(id) ON DELETE CASCADE,
  doctor_id       TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  medicine_name   TEXT NOT NULL,
  system          TEXT NOT NULL DEFAULT 'allopathy',
  dose            TEXT,
  frequency       TEXT,
  duration        TEXT,
  instructions    TEXT,
  attributes      TEXT NOT NULL DEFAULT '{}',  -- JSON, validated per practice pack
  sort_order      INTEGER NOT NULL DEFAULT 0
, dispense_quantity REAL, stock_item_id TEXT);
CREATE TABLE lab_reports (
  id            TEXT PRIMARY KEY,
  doctor_id     TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  patient_id    TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,
  report_name   TEXT NOT NULL,
  reported_on   TEXT NOT NULL,
  source        TEXT,                  -- lab | patient_upload
  status        TEXT NOT NULL DEFAULT 'awaiting_verification',
  verified_by   TEXT,
  verified_at   TEXT,
  file_key      TEXT,                  -- R2 object key
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
, practitioner_id TEXT REFERENCES clinic_users(id), lab_name TEXT, idempotency_key TEXT);
CREATE TABLE lab_values (
  id            TEXT PRIMARY KEY,
  lab_report_id TEXT NOT NULL REFERENCES lab_reports(id) ON DELETE CASCADE,
  doctor_id     TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  analyte       TEXT NOT NULL,
  value         TEXT,
  unit          TEXT,
  reference     TEXT,
  flag          TEXT                    -- normal | high | low | critical
);
CREATE TABLE stock_items (
  id            TEXT PRIMARY KEY,
  doctor_id     TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  medicine_name TEXT NOT NULL,
  system        TEXT NOT NULL DEFAULT 'allopathy',
  form          TEXT,                   -- tablet | syrup | churna | oil
  unit          TEXT,
  reorder_level REAL NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE stock_batches (
  id            TEXT PRIMARY KEY,
  stock_item_id TEXT NOT NULL REFERENCES stock_items(id) ON DELETE CASCADE,
  doctor_id     TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  batch_no      TEXT,
  expires_on    TEXT NOT NULL,
  quantity      REAL NOT NULL DEFAULT 0,
  cost_price    REAL,
  sale_price    REAL,
  received_on   TEXT NOT NULL DEFAULT (date('now'))
, quarantined_at TEXT, quarantine_reason TEXT);
CREATE TABLE stock_movements (
  id            TEXT PRIMARY KEY,
  doctor_id     TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  batch_id      TEXT NOT NULL REFERENCES stock_batches(id) ON DELETE CASCADE,
  patient_id    TEXT REFERENCES patients(id) ON DELETE SET NULL,
  direction     TEXT NOT NULL,          -- in | out | adjust | expired
  quantity      REAL NOT NULL,
  reason        TEXT,
  moved_at      TEXT NOT NULL DEFAULT (datetime('now'))
, prescription_item_id TEXT, operation_id TEXT
  REFERENCES stock_operations(id) ON DELETE SET NULL);
CREATE TABLE consent_grants (
  id                TEXT PRIMARY KEY,
  patient_id        TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,
  granted_to_doctor TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  scope             TEXT NOT NULL DEFAULT 'full_history',
  method            TEXT NOT NULL DEFAULT 'patient_otp',
  granted_at        TEXT NOT NULL DEFAULT (datetime('now')),
  expires_at        TEXT NOT NULL,
  revoked_at        TEXT
);
CREATE TABLE consent_access_log (
  id           TEXT PRIMARY KEY,
  grant_id     TEXT NOT NULL REFERENCES consent_grants(id) ON DELETE CASCADE,
  patient_id   TEXT NOT NULL,
  reader_id    TEXT NOT NULL,           -- the doctor doing the reading
  owner_id     TEXT NOT NULL,           -- the doctor whose record was read
  record_type  TEXT NOT NULL,
  record_id    TEXT,
  accessed_at  TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE audit_events (
  id          TEXT PRIMARY KEY,
  doctor_id   TEXT,
  actor       TEXT NOT NULL,            -- doctor:<id> | platform:<email> | system
  action      TEXT NOT NULL,
  target_type TEXT,
  target_id   TEXT,
  detail      TEXT,
  ip          TEXT,
  created_at  TEXT NOT NULL DEFAULT (datetime('now'))
, actor_user_id TEXT);
CREATE TABLE usage_events (
  id              TEXT PRIMARY KEY,
  doctor_id       TEXT NOT NULL,
  event_type      TEXT NOT NULL,        -- patient_created | rx_issued | ai_run | ...
  quantity        REAL NOT NULL DEFAULT 1,
  unit            TEXT,
  provider        TEXT,
  model           TEXT,
  estimated_cost  REAL,
  idempotency_key TEXT UNIQUE,          -- stops double counting on retry
  metadata        TEXT,
  occurred_at     TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE platform_team (
  email      TEXT PRIMARY KEY,
  full_name  TEXT,
  role       TEXT NOT NULL DEFAULT 'viewer',  -- owner | admin | support | finance | viewer
  added_at   TEXT NOT NULL DEFAULT (datetime('now')),
  removed_at TEXT
, password_hash TEXT, password_salt TEXT, last_sign_in_at TEXT);
CREATE TABLE admin_sessions (
  token_hash TEXT PRIMARY KEY,
  email      TEXT NOT NULL REFERENCES platform_team(email) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  expires_at TEXT NOT NULL,
  user_agent TEXT,
  revoked_at TEXT
, csrf_hash TEXT, reauthenticated_at TEXT);
CREATE TABLE doctor_invites (
  id            TEXT PRIMARY KEY,
  doctor_id     TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  invited_by    TEXT NOT NULL,
  identifier    TEXT NOT NULL,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  first_used_at TEXT
);
CREATE TABLE rx_sequences (
  doctor_id TEXT NOT NULL,
  year      INTEGER NOT NULL,
  next_no   INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY (doctor_id, year)
);
CREATE TABLE patient_access_links (
  id             TEXT PRIMARY KEY,
  token_hash     TEXT NOT NULL UNIQUE,
  patient_id     TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,
  doctor_id      TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  created_by     TEXT NOT NULL,
  requires_otp   INTEGER NOT NULL DEFAULT 0,  -- switched on when SMS is live
  created_at     TEXT NOT NULL DEFAULT (datetime('now')),
  expires_at     TEXT NOT NULL,
  revoked_at     TEXT,
  opened_count   INTEGER NOT NULL DEFAULT 0,
  last_opened_at TEXT
);
CREATE TABLE IF NOT EXISTS "patients" (
  id              TEXT PRIMARY KEY,
  patient_code    TEXT UNIQUE,          -- the person's own identifier
  mobile          TEXT NOT NULL,        -- the household's contact number
  mobile_verified INTEGER NOT NULL DEFAULT 0,
  full_name       TEXT NOT NULL,
  sex             TEXT,
  date_of_birth   TEXT,
  blood_group     TEXT,
  relation        TEXT,                 -- self, spouse, child, parent, other
  created_at      TEXT NOT NULL DEFAULT (datetime('now'))
, abha_number TEXT, abha_address TEXT, abha_status TEXT NOT NULL DEFAULT 'unverified', abha_verified_at TEXT, whatsapp_opt_in INTEGER NOT NULL DEFAULT 0, whatsapp_opt_in_at TEXT, whatsapp_opted_out_at TEXT);
CREATE TABLE appointments (
  id             TEXT PRIMARY KEY,
  doctor_id      TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  patient_id     TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,

  scheduled_on   TEXT NOT NULL,          -- the day
  scheduled_at   TEXT,                   -- HH:MM, optional: walk-in clinics
  duration_mins  INTEGER NOT NULL DEFAULT 15,

  reason         TEXT,
  source         TEXT NOT NULL DEFAULT 'manual',  -- manual | follow_up | phone
  from_visit_id  TEXT REFERENCES visits(id) ON DELETE SET NULL,

  status         TEXT NOT NULL DEFAULT 'scheduled',
                 -- scheduled | arrived | completed | no_show | cancelled
  arrived_at     TEXT,
  completed_at   TEXT,
  cancel_reason  TEXT,

  notes          TEXT,
  created_at     TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at     TEXT
, request_id TEXT
  REFERENCES appointment_requests(id) ON DELETE SET NULL);
CREATE TABLE appointment_requests (
  id            TEXT PRIMARY KEY,
  doctor_id     TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  full_name     TEXT NOT NULL,
  mobile        TEXT NOT NULL,
  preferred_on  TEXT,
  preferred_time TEXT,
  reason        TEXT,
  note          TEXT,
  status        TEXT NOT NULL DEFAULT 'new',   -- new | accepted | declined
  patient_id    TEXT REFERENCES patients(id) ON DELETE SET NULL,
  appointment_id TEXT REFERENCES appointments(id) ON DELETE SET NULL,
  source_ip     TEXT,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  handled_at    TEXT
);
CREATE TABLE drug_catalogue (
  id          TEXT PRIMARY KEY,        -- stable slug, e.g. 'paracetamol'
  system      TEXT NOT NULL,           -- 'allopathy' | 'ayurveda'
  name        TEXT NOT NULL,           -- what gets typed, and printed
  detail      TEXT,                    -- botanical / English name, if any
  search_text TEXT NOT NULL,           -- lowercased name + every synonym
  popularity  INTEGER NOT NULL DEFAULT 0,  -- orders the suggestion list
  source      TEXT NOT NULL,           -- provenance of THIS row
  created_at  TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE drug_strengths (
  drug_id  TEXT NOT NULL REFERENCES drug_catalogue(id) ON DELETE CASCADE,
  strength TEXT NOT NULL,              -- '500mg', '125mg/5ml'
  -- Empty string, never NULL: SQLite permits NULLs in a non-INTEGER primary
  -- key, which would silently let the same strength be inserted twice.
  form     TEXT NOT NULL DEFAULT '',   -- 'Tablet', 'Syrup', ...
  weight   INTEGER NOT NULL DEFAULT 0, -- how common; orders the list
  PRIMARY KEY (drug_id, strength, form)
);
CREATE TABLE patient_sequences (
  doctor_id TEXT PRIMARY KEY REFERENCES doctors(id) ON DELETE CASCADE,
  next_no   INTEGER NOT NULL DEFAULT 1000    -- first handed out is 1001
);
CREATE TABLE clinic_users (
  id            TEXT PRIMARY KEY,
  doctor_id     TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  full_name     TEXT NOT NULL,
  mobile        TEXT NOT NULL UNIQUE,   -- how they sign in; one clinic each
  role          TEXT NOT NULL,          -- front_desk | pharmacist | assistant
  password_hash TEXT,
  password_salt TEXT,

  -- Every staff account starts on a temporary password. It is shown to the
  -- doctor once, never stored in readable form, and must be replaced before
  -- anything opens.
  must_change_password INTEGER NOT NULL DEFAULT 1,

  status        TEXT NOT NULL DEFAULT 'active',   -- active | revoked
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  last_sign_in_at TEXT
, capabilities TEXT, qualification TEXT, registration_no TEXT, council TEXT, verification_status TEXT NOT NULL DEFAULT 'unverified', verified_at TEXT, verified_by TEXT, hpr_id TEXT);
CREATE TABLE invoices (
  id          TEXT PRIMARY KEY,
  doctor_id   TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  patient_id  TEXT NOT NULL REFERENCES patients(id),
  visit_id    TEXT,

  invoice_no  TEXT,                -- assigned on issue, never before
  status      TEXT NOT NULL DEFAULT 'draft',   -- draft | issued | cancelled
  issued_on   TEXT,

  -- all in paise
  subtotal    INTEGER NOT NULL DEFAULT 0,
  discount    INTEGER NOT NULL DEFAULT 0,
  tax_rate    REAL    NOT NULL DEFAULT 0,      -- percent, e.g. 5 or 12
  tax_amount  INTEGER NOT NULL DEFAULT 0,
  total       INTEGER NOT NULL DEFAULT 0,

  note            TEXT,
  cancelled_at    TEXT,
  cancel_reason   TEXT,
  created_at      TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE invoice_items (
  id          TEXT PRIMARY KEY,
  invoice_id  TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
  doctor_id   TEXT NOT NULL,       -- denormalised so isolation holds on this table too
  kind        TEXT NOT NULL DEFAULT 'other',  -- consultation | medicine | procedure | lab | other
  description TEXT NOT NULL,
  quantity    REAL    NOT NULL DEFAULT 1,
  unit_price  INTEGER NOT NULL DEFAULT 0,     -- paise
  amount      INTEGER NOT NULL DEFAULT 0,     -- paise
  sort_order  INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE payments (
  id          TEXT PRIMARY KEY,
  invoice_id  TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
  doctor_id   TEXT NOT NULL,
  amount      INTEGER NOT NULL,    -- paise
  method      TEXT NOT NULL,       -- cash | upi | card | bank | other
  reference   TEXT,                -- UPI ref, last four digits, cheque no
  received_on TEXT NOT NULL,
  received_by TEXT,                -- clinic_users.id, or null for the doctor
  created_at  TEXT NOT NULL DEFAULT (datetime('now'))
, idempotency_key TEXT);
CREATE TABLE invoice_sequences (
  doctor_id TEXT NOT NULL,
  year      INTEGER NOT NULL,
  next_no   INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (doctor_id, year)
);
CREATE TABLE fee_items (
  id          TEXT PRIMARY KEY,
  doctor_id   TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  kind        TEXT NOT NULL DEFAULT 'consultation',
  description TEXT NOT NULL,
  unit_price  INTEGER NOT NULL DEFAULT 0,   -- paise
  active      INTEGER NOT NULL DEFAULT 1,
  created_at  TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE support_requests (
  id          TEXT PRIMARY KEY,
  doctor_id   TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  created_by  TEXT NOT NULL,
  category    TEXT NOT NULL,
  subject     TEXT NOT NULL,
  message     TEXT NOT NULL,
  priority    TEXT NOT NULL DEFAULT 'normal',
  status      TEXT NOT NULL DEFAULT 'open',
  admin_note  TEXT,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at  TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE doctor_applications (
  id               TEXT PRIMARY KEY,

  -- What the doctor typed. Kept exactly as submitted, so that when the
  -- council register disagrees we can see which of the two is wrong.
  full_name        TEXT NOT NULL,
  mobile           TEXT NOT NULL,
  email            TEXT,
  qualification    TEXT,
  registration_no  TEXT,
  council          TEXT,                -- which register to check them against
  clinic_name      TEXT NOT NULL,
  city             TEXT,
  state            TEXT,

  -- Which product they are applying for. Decides the workspace they get on
  -- approval, and it is checked against the qualification: a BHMS asking
  -- for AlloCOS is the exact case a human needs to look at.
  discipline       TEXT NOT NULL DEFAULT 'ayurcos',

  -- "How many people work here" turned out to be two different questions.
  -- Five doctors who opened a place together is a completely different sale
  -- from one doctor with five staff: different pricing, different number of
  -- workspaces, and only one of them needs a shared appointment diary.
  facility_type    TEXT,                -- 'clinic' | 'multi_doctor' | 'hospital'
  doctor_count     INTEGER,             -- practitioners who will see patients
  staff_count      INTEGER,             -- front desk, pharmacy, assistants

  message          TEXT,                -- anything else they want to say
  source           TEXT,                -- which page or campaign sent them

  -- new -> reviewing -> approved | rejected. Nothing is deleted: a rejected
  -- application is evidence that we looked, and a doctor who reapplies
  -- should meet the same history.
  status           TEXT NOT NULL DEFAULT 'new',
  review_note      TEXT,                -- internal, never shown to the doctor
  rejection_reason TEXT,                -- what we would tell them
  reviewed_by      TEXT,                -- platform_team email
  reviewed_at      TEXT,

  -- Set when approved, linking the application to the account it created.
  doctor_id        TEXT REFERENCES doctors(id) ON DELETE SET NULL,

  created_at       TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at       TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE clinic_closures (
  id         TEXT PRIMARY KEY,
  doctor_id  TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,

  -- Inclusive range. A single day is the same date twice, so the diary and
  -- the public page need only one rule to read.
  starts_on  TEXT NOT NULL,
  ends_on    TEXT NOT NULL,

  -- Shown to patients on the public page, so it is written for them:
  -- "Closed for Diwali", not "leave". Optional.
  reason     TEXT,

  -- A half day rather than a full closure: the clinic opens, but on these
  -- hours instead of the weekly ones. NULL means closed all day.
  sessions   TEXT,

  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE cost_rates (
  id              TEXT PRIMARY KEY,     -- matches usage_events.event_type where it can
  label           TEXT NOT NULL,        -- what this is, in words
  category        TEXT NOT NULL,        -- storage | database | messaging | ai | platform
  unit            TEXT NOT NULL,        -- each | per_1000 | gb_month | month
  paise_per_unit  INTEGER NOT NULL DEFAULT 0,
  note            TEXT,                 -- where the number came from
  updated_at      TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE plan_prices (
  plan           TEXT PRIMARY KEY,
  paise_monthly  INTEGER NOT NULL DEFAULT 0,
  updated_at     TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE plan_limits (
  plan           TEXT NOT NULL,
  limit_key      TEXT NOT NULL,   -- patients | staff | doctors | messages | ai_documents | storage_mb
  included       INTEGER NOT NULL DEFAULT 0,
  overage_paise  INTEGER NOT NULL DEFAULT 0,   -- per unit beyond `included`
  hard_stop      INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY (plan, limit_key)
);
CREATE TABLE plan_grace (
  doctor_id    TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  limit_key    TEXT NOT NULL,
  started_at   TEXT NOT NULL DEFAULT (datetime('now')),
  expires_at   TEXT NOT NULL,
  -- What they were over by when it started, so support can see whether this
  -- was a busy week or a plan that no longer fits.
  usage_at_start INTEGER NOT NULL DEFAULT 0,
  notified_at  TEXT,
  PRIMARY KEY (doctor_id, limit_key)
);
CREATE TABLE files (
  id            TEXT PRIMARY KEY,
  doctor_id     TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,

  -- '<doctor_id>/<kind>/<file_id>'. Never derived from anything a caller
  -- sent, so a crafted filename cannot escape the prefix.
  r2_key        TEXT NOT NULL UNIQUE,

  kind          TEXT NOT NULL,        -- certificate | lab_report | logo | attachment
  original_name TEXT,                 -- what she called it, for display only
  content_type  TEXT NOT NULL,
  bytes         INTEGER NOT NULL,

  -- What it belongs to, when it belongs to something.
  patient_id     TEXT REFERENCES patients(id) ON DELETE SET NULL,
  lab_report_id  TEXT REFERENCES lab_reports(id) ON DELETE SET NULL,

  uploaded_by   TEXT,                 -- doctor:<id> or staff:<id>
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),

  -- Soft delete. A file removed from a chart still existed, and a record
  -- that can be silently emptied is not a record.
  deleted_at    TEXT,
  deleted_by    TEXT,
  delete_reason TEXT
);
CREATE TABLE ai_drafts (
  id           TEXT PRIMARY KEY,
  doctor_id    TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  patient_id   TEXT REFERENCES patients(id) ON DELETE SET NULL,
  file_id      TEXT REFERENCES files(id) ON DELETE SET NULL,

  kind         TEXT NOT NULL DEFAULT 'lab_report',

  -- Whether the page could be read at all, and if not, what to tell whoever
  -- photographed it. This is the field that stops a blurred page becoming
  -- invented numbers.
  legible      INTEGER NOT NULL DEFAULT 1,
  legibility_problem TEXT,

  -- Does the name printed on the page belong to the patient this is being
  -- filed against?  same_person | spelling_variant | different_person |
  -- no_name_on_page | not_checked
  --
  -- Columns rather than only fields inside the payload, so the review queue
  -- can put a mismatch at the top without parsing every draft it lists.
  -- Filing a report to the wrong chart is the second way this feature could
  -- hurt somebody, and unlike a misread digit nobody catches it by looking
  -- harder at the numbers.
  name_verdict TEXT,
  name_on_page TEXT,

  -- The whole extraction as the model returned it - every section, every row,
  -- and everything that fitted no field at all. Kept verbatim, including what
  -- was later corrected, because the correction is the useful signal.
  payload      TEXT NOT NULL,

  -- pending -> confirmed | rejected. Nothing reaches the chart at 'pending'.
  status       TEXT NOT NULL DEFAULT 'pending',
  lab_report_id TEXT REFERENCES lab_reports(id) ON DELETE SET NULL,
  reviewed_by  TEXT,
  reviewed_at  TEXT,
  reject_reason TEXT,

  -- Measured, not estimated: the real token counts for this read.
  input_tokens  INTEGER,
  cached_tokens INTEGER,
  output_tokens INTEGER,
  cost_paise    INTEGER,
  model         TEXT,

  created_at   TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE ai_preflights (
  id                TEXT PRIMARY KEY,
  doctor_id         TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  patient_id        TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,
  file_id           TEXT NOT NULL REFERENCES files(id) ON DELETE CASCADE,
  registered_name   TEXT NOT NULL,
  name_on_document  TEXT,
  name_verdict      TEXT NOT NULL,
  name_reason       TEXT,
  legible           INTEGER NOT NULL DEFAULT 1,
  legibility_problem TEXT,
  page_count        INTEGER,
  clinical_pages    TEXT NOT NULL DEFAULT '[]',
  excluded_pages    TEXT NOT NULL DEFAULT '[]',
  page_inventory    TEXT NOT NULL DEFAULT '[]',
  status            TEXT NOT NULL,
  confirmed_by      TEXT,
  confirmation_note TEXT,
  confirmed_at      TEXT,
  consumed_at       TEXT,
  input_tokens      INTEGER NOT NULL DEFAULT 0,
  cached_tokens     INTEGER NOT NULL DEFAULT 0,
  output_tokens     INTEGER NOT NULL DEFAULT 0,
  cost_paise        INTEGER NOT NULL DEFAULT 0,
  model             TEXT,
  created_at        TEXT NOT NULL DEFAULT (datetime('now')),
  CHECK (name_verdict IN ('same_person','needs_confirmation','different_person','no_name_on_document')),
  CHECK (status IN ('approved','awaiting_confirmation','blocked','rejected'))
);
CREATE TABLE ai_spend (
  id            TEXT PRIMARY KEY,
  doctor_id     TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,

  kind          TEXT NOT NULL,        -- preflight | extraction
  model         TEXT,

  -- Recorded even when outcome is not 'ok'. Tokens spent on a call that
  -- then failed to parse are still tokens somebody paid for.
  input_tokens  INTEGER NOT NULL DEFAULT 0,
  cached_tokens INTEGER NOT NULL DEFAULT 0,
  output_tokens INTEGER NOT NULL DEFAULT 0,
  cost_paise    INTEGER NOT NULL DEFAULT 0,

  -- ok        the call returned something usable
  -- failed    the provider errored, or the answer could not be used
  -- refused   the model declined
  -- blocked   the guard stopped it BEFORE calling, so cost_paise is 0
  outcome       TEXT NOT NULL DEFAULT 'ok',
  detail        TEXT,
  duration_ms   INTEGER,

  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
, batched INTEGER NOT NULL DEFAULT 0);
CREATE TABLE ai_breaker (
  -- 'platform', or 'doctor:<id>'. One row per thing that can be stopped
  -- independently, so one clinic's runaway does not stop every other clinic.
  scope         TEXT PRIMARY KEY,

  -- closed     normal
  -- open       stopped; calls are refused and documents are queued
  -- half_open  one call allowed through to see whether it is safe again
  state         TEXT NOT NULL DEFAULT 'closed',

  reason        TEXT,                 -- in words an admin can act on
  tripped_at    TEXT,
  -- When to try again on its own. A breaker that only a human can reset
  -- becomes a breaker nobody resets, and the feature stays dead all weekend.
  resets_at     TEXT,
  window_paise  INTEGER,              -- what was spent in the window that tripped it
  notified_at   TEXT,                 -- so the admin is told once, not every call
  cleared_at    TEXT,
  cleared_by    TEXT
);
CREATE TABLE ai_queue (
  id            TEXT PRIMARY KEY,
  doctor_id     TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  patient_id    TEXT REFERENCES patients(id) ON DELETE SET NULL,
  file_id       TEXT REFERENCES files(id) ON DELETE SET NULL,
  kind          TEXT NOT NULL DEFAULT 'preflight',

  -- waiting | done | abandoned
  status        TEXT NOT NULL DEFAULT 'waiting',
  attempts      INTEGER NOT NULL DEFAULT 0,
  last_error    TEXT,

  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  processed_at  TEXT
, batch_id TEXT, provider_status TEXT, preflight_id TEXT, urgency TEXT NOT NULL DEFAULT 'normal', draft_id TEXT, provider_input_file_id TEXT, provider_output_file_id TEXT, provider_error_file_id TEXT, provider_cleanup_status TEXT NOT NULL DEFAULT 'not_needed', provider_cleanup_error TEXT, provider_cleanup_attempts INTEGER NOT NULL DEFAULT 0, provider_cleanup_last_attempt_at TEXT, provider_files_deleted_at TEXT);
CREATE TABLE ai_limits (
  key           TEXT PRIMARY KEY,
  value_paise   INTEGER NOT NULL,
  note          TEXT
);
CREATE TABLE abdm_care_contexts (
  id            TEXT PRIMARY KEY,
  doctor_id     TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  patient_id    TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,

  -- visit | prescription | diagnostic_report
  record_type   TEXT NOT NULL,
  record_id     TEXT NOT NULL,

  -- What ABDM knows it as, and what the patient sees in their locker.
  reference     TEXT NOT NULL,
  display       TEXT NOT NULL,

  -- pending | linked | failed | withdrawn
  status        TEXT NOT NULL DEFAULT 'pending',
  linked_at     TEXT,
  last_error    TEXT,
  attempts      INTEGER NOT NULL DEFAULT 0,

  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE messages (
  id            TEXT PRIMARY KEY,
  doctor_id     TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  patient_id    TEXT REFERENCES patients(id) ON DELETE SET NULL,

  channel       TEXT NOT NULL DEFAULT 'whatsapp',
  template      TEXT NOT NULL,          -- appointment_reminder | record_ready
  to_mobile     TEXT NOT NULL,

  -- What the patient actually saw, in plain text. Not a template id: when a
  -- patient rings up asking why she got a message, the front desk needs to
  -- read the message, not decode a reference.
  body_preview  TEXT,

  -- What it was about, so a cancelled appointment can find its reminder.
  about_type    TEXT,                   -- appointment | prescription | lab_report
  about_id      TEXT,

  -- queued | sent | delivered | read | failed
  status        TEXT NOT NULL DEFAULT 'queued',
  provider_id   TEXT,                   -- Meta's message id, for delivery receipts
  error         TEXT,

  -- The thing that makes a double-send impossible. See the note above.
  dedupe_key    TEXT NOT NULL UNIQUE,

  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  sent_at       TEXT,
  updated_at    TEXT
);
CREATE TABLE consult_notes (
  id            TEXT PRIMARY KEY,
  doctor_id     TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  patient_id    TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,
  -- Set once the doctor confirms and the note is written onto a visit.
  visit_id      TEXT REFERENCES visits(id) ON DELETE SET NULL,

  -- ---------------------------------------------------------- consent ---
  -- Recorded BEFORE the microphone opens. Who took it matters: the front
  -- desk asking is different from the doctor asking, and a complaint six
  -- months later is about exactly that.
  consent_at    TEXT NOT NULL,
  consent_by    TEXT NOT NULL,          -- 'doctor:<id>' or 'staff:<id>'

  -- ------------------------------------------------------------ audio ---
  -- NULLed when the object is deleted, so a row can never point at bytes
  -- that are gone, and a row with a key is a row still holding a voice.
  audio_key     TEXT,
  audio_seconds INTEGER,
  audio_deleted_at TEXT,

  -- ----------------------------------------------------- what was said ---
  -- Consultations in India are rarely in one language. The transcript keeps
  -- whatever was actually spoken - Hindi, Telugu, English, or all three in
  -- one sentence - because translating before the doctor has read it loses
  -- the patient's own words, which are sometimes the diagnosis.
  language      TEXT,
  transcript    TEXT,

  -- --------------------------------------------------- the drafted note ---
  -- Separate columns rather than one blob: the doctor edits section by
  -- section, and a half-corrected note must be storable.
  complaints    TEXT,
  history       TEXT,
  examination   TEXT,
  advice        TEXT,
  follow_up     TEXT,

  -- recording | transcribing | ready | confirmed | rejected | failed
  status        TEXT NOT NULL DEFAULT 'recording',
  error         TEXT,
  cost_paise    INTEGER NOT NULL DEFAULT 0,

  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT
, speakers TEXT, speaker_confidence TEXT NOT NULL DEFAULT 'unclear');
CREATE TABLE subscription_plan_catalog (
  id                TEXT PRIMARY KEY,
  provider          TEXT NOT NULL DEFAULT 'razorpay',
  plan              TEXT NOT NULL,
  cadence           TEXT NOT NULL,
  price_paise       INTEGER NOT NULL,
  currency          TEXT NOT NULL DEFAULT 'INR',
  provider_plan_id  TEXT,
  active            INTEGER NOT NULL DEFAULT 1,
  synced_at         TEXT,
  created_at        TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at        TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (provider, provider_plan_id),
  UNIQUE (provider, plan, cadence, price_paise),
  CHECK (plan IN ('starter','pro','pro_plus')),
  CHECK (cadence IN ('monthly','yearly')),
  CHECK (price_paise > 0)
);
CREATE TABLE subscriptions (
  id                        TEXT PRIMARY KEY,
  doctor_id                 TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  provider                  TEXT NOT NULL DEFAULT 'razorpay',
  provider_subscription_id  TEXT NOT NULL,
  provider_plan_id          TEXT NOT NULL,
  plan                      TEXT NOT NULL,
  cadence                   TEXT NOT NULL,
  price_paise               INTEGER NOT NULL,
  currency                  TEXT NOT NULL DEFAULT 'INR',
  status                    TEXT NOT NULL DEFAULT 'created',
  checkout_url              TEXT,
  current_start             TEXT,
  current_end               TEXT,
  access_until              TEXT,
  cancel_at_cycle_end       INTEGER NOT NULL DEFAULT 0,
  last_provider_event_at    INTEGER,
  created_at                TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at                TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (provider, provider_subscription_id),
  CHECK (plan IN ('starter','pro','pro_plus')),
  CHECK (cadence IN ('monthly','yearly')),
  CHECK (status IN ('created','authenticated','active','pending','halted',
                    'paused','cancelled','completed','expired'))
);
CREATE TABLE payment_webhook_events (
  provider          TEXT NOT NULL,
  event_id          TEXT NOT NULL,
  event_type        TEXT NOT NULL,
  payload_sha256    TEXT NOT NULL,
  status            TEXT NOT NULL DEFAULT 'received',
  attempts          INTEGER NOT NULL DEFAULT 0,
  last_error        TEXT,
  received_at       TEXT NOT NULL DEFAULT (datetime('now')),
  last_attempt_at   TEXT,
  processed_at      TEXT,
  PRIMARY KEY (provider, event_id),
  CHECK (status IN ('received','processing','processed','ignored','failed'))
);
CREATE TABLE subscription_payments (
  id                    TEXT PRIMARY KEY,
  doctor_id             TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  subscription_id       TEXT NOT NULL REFERENCES subscriptions(id) ON DELETE CASCADE,
  provider              TEXT NOT NULL DEFAULT 'razorpay',
  provider_payment_id   TEXT NOT NULL,
  provider_invoice_id   TEXT,
  amount_paise          INTEGER NOT NULL DEFAULT 0,
  currency              TEXT NOT NULL DEFAULT 'INR',
  status                TEXT NOT NULL,
  occurred_at           TEXT,
  recorded_at           TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (provider, provider_payment_id)
);
CREATE TABLE stock_operations (
  id             TEXT PRIMARY KEY,
  doctor_id      TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  operation_key  TEXT NOT NULL,
  kind           TEXT NOT NULL,
  target_id      TEXT,
  quantity       REAL,
  result_json    TEXT NOT NULL DEFAULT '{}',
  actor          TEXT NOT NULL,
  created_at     TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (doctor_id, operation_key)
);
CREATE TABLE patient_registration_operations (
  id             TEXT PRIMARY KEY,
  doctor_id      TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  operation_key  TEXT NOT NULL,
  patient_id     TEXT REFERENCES patients(id) ON DELETE SET NULL,
  local_ref      TEXT,
  actor          TEXT NOT NULL,
  created_at     TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (doctor_id, operation_key)
);
CREATE TABLE auth_throttles (
  scope             TEXT NOT NULL,
  key_hash          TEXT NOT NULL,
  failures          INTEGER NOT NULL DEFAULT 0 CHECK (failures >= 0),
  window_started_at TEXT NOT NULL,
  blocked_until     TEXT,
  updated_at        TEXT NOT NULL,
  PRIMARY KEY (scope, key_hash)
);
